package com.tracksphere.application.location;
import com.tracksphere.application.location.dto.*; import com.tracksphere.domain.model.Location; import com.tracksphere.domain.repository.LocationRepository; import lombok.RequiredArgsConstructor; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class LocationService { private final LocationRepository locations; private final SimpMessagingTemplate messages; public LocationResponse record(LocationRequest r){Location l=locations.save(new Location(r.vehicleId(),r.latitude(),r.longitude(),r.accuracyMeters(),r.recordedAt()));LocationResponse response=map(l);messages.convertAndSend("/topic/locations",response);return response;} @Transactional(readOnly=true) public Optional<LocationResponse> latest(String vehicleId){return locations.findFirstByVehicleIdOrderByRecordedAtDesc(vehicleId).map(this::map);}@Transactional(readOnly=true) public List<LocationResponse> history(String vehicleId,Instant from,Instant to){return locations.findByVehicleIdAndRecordedAtBetweenOrderByRecordedAtDesc(vehicleId,from==null?Instant.EPOCH:from,to==null?Instant.now():to).stream().map(this::map).toList();}@Transactional(readOnly=true) public List<LocationResponse> live(){return locations.findTop100ByOrderByRecordedAtDesc().stream().map(this::map).toList();}private LocationResponse map(Location l){return new LocationResponse(l.getId(),l.getVehicleId(),l.getLatitude(),l.getLongitude(),l.getAccuracyMeters(),l.getRecordedAt());} }
